/* Static English meanings. Original Arabic, IDs, counts and grading remain authoritative. */
const dhikrEnglishData={"schema":1,"language":"en","kind":"english-meanings","scope":"195 selected adhkar and supplications; full Arabic hadith library is separate","sunnahTranslation":"Mushafi English rendering of the meanings of the exact bundled Arabic excerpts; not an independently authenticated or publisher-certified translation","quranTranslation":"Existing verbatim Saheeh International dataset from Tanzil","entries":{"routine-kursi":{"title":"Ayat al-Kursi","meaning":"[2:255] Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.","arabicSha256":"c826c8de989a783d07855b47df70889895bfae4e99f2dbd39fdae5e2911f11d2","reference":"Al-Baqarah 255","quranBlocks":[{"keys":["2:255"],"basmala":false}]},"surah-112":{"title":"Surah Al-Ikhlas","meaning":"In the name of Allah, the Entirely Merciful, the Especially Merciful.\n[112:1] Say, \"He is Allah, [who is] One,\n[112:2] Allah, the Eternal Refuge.\n[112:3] He neither begets nor is born,\n[112:4] Nor is there to Him any equivalent.\"","arabicSha256":"37447359d456392ecb36baaca092479a6ec08d6e5c89385742d83e901dc08943","reference":"Al-Ikhlas 1–4","quranBlocks":[{"keys":["112:1","112:2","112:3","112:4"],"basmala":true}]},"surah-113":{"title":"Surah Al-Falaq","meaning":"In the name of Allah, the Entirely Merciful, the Especially Merciful.\n[113:1] Say, \"I seek refuge in the Lord of daybreak\n[113:2] From the evil of that which He created\n[113:3] And from the evil of darkness when it settles\n[113:4] And from the evil of the blowers in knots\n[113:5] And from the evil of an envier when he envies.\"","arabicSha256":"355ce482a7f3f87cb7061794c3b9fbcfb8d1c830b28b293d835bab530186dd66","reference":"Al-Falaq 1–5","quranBlocks":[{"keys":["113:1","113:2","113:3","113:4","113:5"],"basmala":true}]},"surah-114":{"title":"Surah An-Nas","meaning":"In the name of Allah, the Entirely Merciful, the Especially Merciful.\n[114:1] Say, \"I seek refuge in the Lord of mankind,\n[114:2] The Sovereign of mankind.\n[114:3] The God of mankind,\n[114:4] From the evil of the retreating whisperer -\n[114:5] Who whispers [evil] into the breasts of mankind -\n[114:6] From among the jinn and mankind.\"","arabicSha256":"dbe8bd9fb168c7f74898b4ce2da84cd24af7053425009f78a1ee352419570338","reference":"An-Nas 1–6","quranBlocks":[{"keys":["114:1","114:2","114:3","114:4","114:5","114:6"],"basmala":true}]},"morning-king":{"title":"Entering the morning","meaning":"We have entered the morning, and all sovereignty belongs to Allah. All praise belongs to Allah. There is no god but Allah alone, with no partner. To Him belong sovereignty and praise, and He has power over all things. My Lord, I ask You for the good of this day and the good that follows it, and I seek refuge in You from the evil of this day and the evil that follows it. My Lord, I seek refuge in You from laziness and the infirmity of old age. My Lord, I seek refuge in You from punishment in the Fire and punishment in the grave.","arabicSha256":"e7d4bdd999312652a757e7e350cfff1e14bb5ee3b5a698c02df841d5fc658c0d","reference":"Sahih Muslim 2723b"},"evening-king":{"title":"Entering the evening","meaning":"We have entered the evening, and all sovereignty belongs to Allah. All praise belongs to Allah. There is no god but Allah alone, with no partner. To Him belong sovereignty and praise, and He has power over all things. My Lord, I ask You for the good of this night and the good that follows it, and I seek refuge in You from the evil of this night and the evil that follows it. My Lord, I seek refuge in You from laziness and the infirmity of old age. My Lord, I seek refuge in You from punishment in the Fire and punishment in the grave.","arabicSha256":"d2ad5239139421f2398d8ce8df826fbf7f3d9ee69805dc0ab5eb322950d15516","reference":"Sahih Muslim 2723b"},"morning-life":{"title":"By You we enter the morning","meaning":"O Allah, by You we enter the morning and by You we enter the evening; by You we live and by You we die, and to You is the resurrection.","arabicSha256":"3856c995e9b2ca38ad0ee3db2755286e08eb91b14717ab7223e9a5eb0c4ef1eb","reference":"Sunan Abi Dawud 5068"},"evening-life":{"title":"By You we enter the evening","meaning":"O Allah, by You we enter the evening and by You we enter the morning; by You we live and by You we die, and to You is the final return.","arabicSha256":"414b11db40051fda620a7ae8338473f95e3eeb2e84860ae1f4168ee7e862a5df","reference":"Sunan Ibn Majah 3868"},"sayyid":{"title":"The foremost prayer for forgiveness","meaning":"O Allah, You are my Lord. There is no god but You. You created me and I am Your servant. I uphold my covenant and promise to You as far as I am able. I seek refuge in You from the evil of what I have done. I acknowledge Your blessings upon me and I acknowledge my sin, so forgive me, for none forgives sins but You.","arabicSha256":"ee192996323bdea977b23cc8e73879e3454733d92116ab88c581f21d8ca25232","reference":"Sahih al-Bukhari 6306"},"routine-afiya":{"title":"Well-being and protection","meaning":"O Allah, I ask You for well-being in this world and the Hereafter. O Allah, I ask You for pardon and well-being in my religion, my worldly life, my family and my wealth. O Allah, conceal my faults and calm my fears. O Allah, protect me from in front of me, from behind me, on my right, on my left and from above me. I seek refuge in Your greatness from being taken unawares from beneath me.","arabicSha256":"d5858892094785faf711e2c7cab64cdfd4fb706a363bdc006a36016429790176","reference":"Sunan Abi Dawud 5074"},"routine-body":{"title":"Health in body, hearing and sight","meaning":"O Allah, grant health to my body. O Allah, grant health to my hearing. O Allah, grant health to my sight. There is no god but You.","arabicSha256":"e795306d9dad447a5fb0bfbf4a8962f1dffa4fc5679d7ce90f3f0d1b6f306c3f","reference":"Sunan Abi Dawud 5090"},"routine-poverty":{"title":"Refuge from disbelief and poverty","meaning":"O Allah, I seek refuge in You from disbelief and poverty, and I seek refuge in You from punishment in the grave. There is no god but You.","arabicSha256":"7c09113f13002b54ef1cec0ad5ef9c6ceac55d34040ec605c7a21f3206e53df6","reference":"Sunan Abi Dawud 5090"},"morning-fater":{"title":"Refuge from the self and Satan","meaning":"O Allah, Originator of the heavens and the earth, Knower of the unseen and the seen, Lord and Sovereign of all things: I bear witness that there is no god but You. I seek refuge in You from the evil of my own self, from the evil of Satan and his call to associate partners with You, and from committing evil against myself or bringing it upon a Muslim.","arabicSha256":"17d6d9e44297c05268392f0d5b9891487a359d967315c8d744b70bdfa2f067a7","reference":"Musnad Ahmad and Al-Adab al-Mufrad — wording in Tuhfat al-Akhyar"},"protection":{"title":"In Allah's name: protection","meaning":"In the name of Allah, with whose name nothing on earth or in heaven can cause harm. He is the All-Hearing, the All-Knowing.","arabicSha256":"11e4592ac3caf3d5485a59b622c15b29261664528eea8aea01cd8dab19cd5e7e","reference":"Sunan Abi Dawud 5088; Jami' al-Tirmidhi 3388"},"routine-ridha":{"title":"Contentment with Allah, Islam and the Prophet","meaning":"I am content with Allah as my Lord, Islam as my religion, and Muhammad, may Allah bless him and grant him peace, as my Prophet.","arabicSha256":"f5578d12704a31bf76880f7f5766ee1e6e12fd6259a74df34d56d82db715690f","reference":"Musnad Ahmad — wording in Tuhfat al-Akhyar"},"routine-witness-morning":{"title":"Bearing witness in the morning","meaning":"O Allah, this morning I call You, the bearers of Your Throne, Your angels and all Your creation to witness that You are Allah; there is no god but You alone, with no partner, and that Muhammad is Your servant and Messenger.","arabicSha256":"b9083026c02a0b3350ee8dc9cb8203c60c650efdc8980b397a9c66a19e710cba","reference":"Sunan Abi Dawud 5069"},"routine-witness-evening":{"title":"Bearing witness in the evening","meaning":"O Allah, this evening I call You, the bearers of Your Throne, Your angels and all Your creation to witness that You are Allah; there is no god but You alone, with no partner, and that Muhammad is Your servant and Messenger.","arabicSha256":"9853a191e750510f305688eae3f2a688119509ecf2d4b2919ead561e0003a98c","reference":"Sunan Abi Dawud 5069; evening wording in Hisn al-Muslim"},"routine-thanks-morning":{"title":"Gratitude for blessings in the morning","meaning":"O Allah, whatever blessing has come to me or to any of Your creation this morning is from You alone, with no partner. To You belong all praise and all thanks.","arabicSha256":"3a7776e368fba73eba1955caf817a7ec9a1a66762a8e5145c1c1cd7086ad3b86","reference":"Abu Dawud 5073 and al-Nasa'i, 'Amal al-Yawm wa al-Laylah — wording in Tuhfat al-Akhyar"},"routine-thanks-evening":{"title":"Gratitude for blessings in the evening","meaning":"O Allah, whatever blessing has come to me or to any of Your creation this evening is from You alone, with no partner. To You belong all praise and all thanks.","arabicSha256":"0a126249abdca152b01ba2665367661019a5ad17732258752be80c28f39491d2","reference":"Abu Dawud 5073 and al-Nasa'i; evening wording in Hisn al-Muslim"},"routine-fitra-morning":{"title":"The faith of Islam: morning","meaning":"We have entered the morning upon the natural faith of Islam, the word of sincere devotion, the religion of our Prophet Muhammad, may Allah bless him and grant him peace, and the way of our father Abraham, who was upright, a Muslim, and not one of those who associated partners with Allah.","arabicSha256":"fc46a02c7dc0e6e8b357ab8f3fe9ffae9ce17c81aa00c886b386ec4a13fd227d","reference":"Musnad Ahmad — the hadith of the natural faith in Tuhfat al-Akhyar"},"routine-fitra-evening":{"title":"The faith of Islam: evening","meaning":"We have entered the evening upon the natural faith of Islam, the word of sincere devotion, the religion of our Prophet Muhammad, may Allah bless him and grant him peace, and the way of our father Abraham, who was upright, a Muslim, and not one of those who associated partners with Allah.","arabicSha256":"f08a4ed52c6bd22fff86c02173aca5df748f5395de55439ff131db8b04843db0","reference":"Musnad Ahmad; evening wording in Hisn al-Muslim"},"routine-hayy":{"title":"O Ever-Living, O Sustainer","meaning":"O Ever-Living, O Sustainer of all, I seek help through Your mercy. Set all my affairs right, and do not leave me to myself even for the blink of an eye.","arabicSha256":"7fff4e2d98262e4830f9279ef9e6e8809603cbd2717bdc4381f8783533079277","reference":"Al-Nasa'i, Al-Sunan al-Kubra; Sahih al-Targhib 661"},"morning-tasbih":{"title":"Glorifying and praising Allah","meaning":"Glory be to Allah, and praise be to Him.","arabicSha256":"ebb3c7dfdab1e22c2860d1b4f92c1c82d041795a652a8156ac90e95807755ec4","reference":"Sahih Muslim 2692"},"routine-tahlil10":{"title":"Declaring Allah's oneness ten times","meaning":"There is no god but Allah alone, with no partner. To Him belong sovereignty and praise, and He has power over all things.","arabicSha256":"af3597c05b7b01bcfb76b7da036a41416ad03b7d411ddb3180d83d91dceaf840","reference":"Musnad Ahmad — declaring Allah's oneness ten times, in Tuhfat al-Akhyar"},"routine-tahlil100":{"title":"Declaring Allah's oneness a hundred times daily","meaning":"There is no god but Allah alone, with no partner. To Him belong sovereignty and praise, and He has power over all things.","arabicSha256":"af3597c05b7b01bcfb76b7da036a41416ad03b7d411ddb3180d83d91dceaf840","reference":"Sahih al-Bukhari 3293; Sahih Muslim 2691"},"routine-creation":{"title":"Praise as vast as creation","meaning":"Glory be to Allah, and praise be to Him, as many times as His creation, as much as pleases Him, as weighty as His Throne, and as abundant as the ink of His words.","arabicSha256":"cb490b8604e99f9727a142fb4ba6d6ef5ef858f6eebece1ee179b1dc8f105137","reference":"Sahih Muslim 2726a"},"routine-fajr-knowledge":{"title":"After the Fajr prayer","meaning":"O Allah, I ask You for beneficial knowledge, wholesome provision, and deeds that are accepted.","arabicSha256":"5c74693771523715680571feb6843b8d2fbaf56d312f81dcf59ec5a0a968cf33","reference":"Sunan Ibn Majah 925"},"routine-words-evening":{"title":"Refuge in Allah's perfect words","meaning":"I seek refuge in the perfect words of Allah from the evil of what He has created.","arabicSha256":"30e0e3b7d7ba435d11a0b3acefe56df205d2bea5e64bce64d93559746ac4e9d2","reference":"Jami' al-Tirmidhi 3604b; also reported in Sahih Muslim 2709"},"sleep-name":{"title":"When going to sleep","meaning":"In Your name, O Allah, I die and I live.","arabicSha256":"654f5adca985550602b79feb72ef6a211bf49c6aab78afca71b29679388b8522","reference":"Sahih al-Bukhari 6324"},"wakeup":{"title":"When waking up","meaning":"All praise belongs to Allah, who has brought us to life after causing us to die, and to Him is the resurrection.","arabicSha256":"af74f57d89cd4062d918b4aee7b1ef6917848fdc27492fdfebe520e870622c6b","reference":"Sahih al-Bukhari 6324"},"prayer-istighfar":{"title":"Seeking forgiveness after prayer","meaning":"I seek Allah's forgiveness.","arabicSha256":"9ef913a347672f03b6c0b851c3a052ebd52c61a9ff40c76f1e76d932d031117f","reference":"Sahih Muslim 591"},"prayer-salam":{"title":"O Allah, You are Peace","meaning":"O Allah, You are Peace and from You comes peace. Blessed are You, Possessor of majesty and honour.","arabicSha256":"3840c67e4e5a5e049559fab53d9d6c6f134a9da0104eefb5b918eb48ee2f030d","reference":"Sahih Muslim 591"},"prayer-subhan":{"title":"Glorification after prayer","meaning":"Glory be to Allah.","arabicSha256":"b5e0d9085ab0f48ddd30e15594aaa8da28b0e9faa07e73062bbb09b2eaf5dac3","reference":"Sahih Muslim 597"},"prayer-hamd":{"title":"Praise after prayer","meaning":"All praise belongs to Allah.","arabicSha256":"64d2fd2e2ac9ee8cfa866e3c68772059a1818ce6beb1703641dccf011b486c11","reference":"Sahih Muslim 597"},"prayer-akbar":{"title":"Magnifying Allah after prayer","meaning":"Allah is the Greatest.","arabicSha256":"8815ef4c70eedd27151d862434eaf3a8f930e5b44b54909fba74817b32b7cca8","reference":"Sahih Muslim 597"},"prayer-tahlil":{"title":"Completing one hundred after prayer","meaning":"There is no god but Allah alone, with no partner. To Him belong sovereignty and praise, and He has power over all things.","arabicSha256":"6d4e93101c3d3e9ffe9b4ff86ed30704501cedb4e3971491fb8ed80cba13283c","reference":"Sahih Muslim 597a"},"prayer-help":{"title":"Seeking help with worship","meaning":"O Allah, help me to remember You, to thank You, and to worship You well.","arabicSha256":"8c02873d0701f4dd02fb90b3d1c5935b5ce57bdc6777ddcbbff040f78e00a931","reference":"Sunan Abi Dawud 1522"},"food-forgot":{"title":"If you forget before eating","meaning":"In the name of Allah, at its beginning and its end.","arabicSha256":"9a2b151a0878313ce61e29d1a327fc67973ed0b2917c484e9d86a001a84a4f9c","reference":"Sunan Abi Dawud 3767"},"food-end":{"title":"After eating","meaning":"All praise belongs to Allah, who has fed me this food and provided it for me without any power or strength on my part.","arabicSha256":"d1ec0f02fac8a4ed9a8160a27dd105fbe0ea653844a6701e645019baae888d6d","reference":"Sunan Abi Dawud 4023"},"leave-home":{"title":"When leaving home","meaning":"In the name of Allah. I put my trust in Allah. There is no power and no strength except through Allah.","arabicSha256":"33e98e886d67e66657f1471e5cc0444be8b7153efffdae7a087b2e9a8977e351","reference":"Sunan Abi Dawud 5095"},"mosque-enter":{"title":"When entering the mosque","meaning":"O Allah, open for me the gates of Your mercy.","arabicSha256":"ba5d9d688cc88dfd23eb9d17f413355f889801ddceb508c4adf94b44c51bc069","reference":"Sahih Muslim 713a"},"mosque-leave":{"title":"When leaving the mosque","meaning":"O Allah, I ask You for Your bounty.","arabicSha256":"08cc07bfe5d00b020184279df823c77bf15f2dd4d154e4cc0ae155ea940ca788","reference":"Sahih Muslim 713a"},"bathroom-enter":{"title":"Before entering the toilet","meaning":"O Allah, I seek refuge in You from male and female devils.","arabicSha256":"6271ced14d2f1a8bef97eaeade0cbefce39669f7249301c3a85f91684c1987af","reference":"Sahih al-Bukhari 142"},"bathroom-leave":{"title":"After leaving the toilet","meaning":"I ask Your forgiveness.","arabicSha256":"b9c094071a52749920a3e0624d2f980951915db284649c3ae052a6e4c8841468","reference":"Sunan Abi Dawud 30"},"worry":{"title":"Anxiety and sorrow","meaning":"O Allah, I seek refuge in You from anxiety and sorrow, inability and laziness, cowardice and miserliness, the burden of debt, and being overpowered by others.","arabicSha256":"1c1250d440751ce835e6c40ed3f6c1dc1accd3b2f10486d94f8a3f9fa2903c3c","reference":"Sahih al-Bukhari 6369"},"guidance":{"title":"Guidance and righteousness","meaning":"O Allah, I ask You for guidance, righteousness, chastity and self-sufficiency.","arabicSha256":"64b13693f36e4cf50f626b68d7bc11b89ac2f11ddfb8b9d4eefc2fe47586d4cb","reference":"Sahih Muslim 2721a"},"healing":{"title":"For someone who is ill","meaning":"O Allah, Lord of mankind, remove the affliction. Heal him, for You are the Healer. There is no healing but Your healing: a healing that leaves no illness.","arabicSha256":"dbd251a88f2560635eec63add3143213c98408d64b1c1243f077c642bfb6158a","reference":"Sahih al-Bukhari 5743"},"pardon":{"title":"Asking for pardon","meaning":"O Allah, You are Pardoning and You love to pardon, so pardon me.","arabicSha256":"f8b8f765386d060fe6a207ac05d5f94b9a721c41745ad65a5ba906a12c5ac573","reference":"Sunan Ibn Majah 3850"},"sleep-subhan":{"title":"Glorification before sleep","meaning":"Glory be to Allah.","arabicSha256":"b5e0d9085ab0f48ddd30e15594aaa8da28b0e9faa07e73062bbb09b2eaf5dac3","reference":"Sahih Muslim 2727"},"sleep-hamd":{"title":"Praise before sleep","meaning":"All praise belongs to Allah.","arabicSha256":"64d2fd2e2ac9ee8cfa866e3c68772059a1818ce6beb1703641dccf011b486c11","reference":"Sahih Muslim 2727"},"sleep-akbar":{"title":"Magnifying Allah before sleep","meaning":"Allah is the Greatest.","arabicSha256":"8815ef4c70eedd27151d862434eaf3a8f930e5b44b54909fba74817b32b7cca8","reference":"Sahih Muslim 2727"},"kursi":{"title":"Ayat al-Kursi","meaning":"[2:255] Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.","arabicSha256":"c826c8de989a783d07855b47df70889895bfae4e99f2dbd39fdae5e2911f11d2","reference":"Al-Baqarah 255","quranBlocks":[{"keys":["2:255"],"basmala":false}]},"baqara-last":{"title":"The last two verses of Al-Baqarah","meaning":"[2:285] The Messenger has believed in what was revealed to him from his Lord, and [so have] the believers. All of them have believed in Allah and His angels and His books and His messengers, [saying], \"We make no distinction between any of His messengers.\" And they say, \"We hear and we obey. [We seek] Your forgiveness, our Lord, and to You is the [final] destination.\"\n[2:286] Allah does not charge a soul except [with that within] its capacity. It will have [the consequence of] what [good] it has gained, and it will bear [the consequence of] what [evil] it has earned. \"Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people.\"","arabicSha256":"d920060cf204fb33d8ea51bd643bfdc37920cafbb05ac03df93ce993e9ca8875","reference":"Al-Baqarah 285–286","quranBlocks":[{"keys":["2:285","2:286"],"basmala":false}]},"quran-2-201":{"title":"Good in this world and the Hereafter","meaning":"[2:201] But among them is he who says, \"Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire.\"","arabicSha256":"e8201ab9bf74ac0e842ace8c4240f68389c8b78a1f7baa4ccde904154ae985d0","reference":"Al-Baqarah 201","quranBlocks":[{"keys":["2:201"],"basmala":false}]},"quran-2-286":{"title":"Pardon and forgiveness","meaning":"[2:286] Allah does not charge a soul except [with that within] its capacity. It will have [the consequence of] what [good] it has gained, and it will bear [the consequence of] what [evil] it has earned. \"Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people.\"","arabicSha256":"7e3b683bb87f716f777ab6f75d6bd84cf723c741fc8288283d81ac4552ca65ff","reference":"Al-Baqarah 286","quranBlocks":[{"keys":["2:286"],"basmala":false}]},"quran-3-8":{"title":"Steadfastness and guidance","meaning":"[3:8] [Who say], \"Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.","arabicSha256":"62a4307c2fe5d6e8be0b4df3f0f2a6ad24736477a01d8b8d66b91a43def47d4c","reference":"Ali 'Imran 8","quranBlocks":[{"keys":["3:8"],"basmala":false}]},"quran-3-9":{"title":"Belief in the promised gathering","meaning":"[3:9] Our Lord, surely You will gather the people for a Day about which there is no doubt. Indeed, Allah does not fail in His promise.\"","arabicSha256":"c241ca76bf66d0013069974f88e8f75c86560df6ce162e195ee9603f7772f2c5","reference":"Ali 'Imran 9","quranBlocks":[{"keys":["3:9"],"basmala":false}]},"quran-3-16":{"title":"Asking for forgiveness","meaning":"[3:16] Those who say, \"Our Lord, indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire,\"","arabicSha256":"d7be5d6491e6781d09ec1f698bbee31b26bd03d91e841f9a6bda1e88c2a79319","reference":"Ali 'Imran 16","quranBlocks":[{"keys":["3:16"],"basmala":false}]},"quran-3-53":{"title":"Faith and following the Messenger","meaning":"[3:53] Our Lord, we have believed in what You revealed and have followed the messenger Jesus, so register us among the witnesses [to truth].\"","arabicSha256":"730912fdbaf142440e8e4fbb5a57207fadd2b7103842e0bbd25364ef795f01c6","reference":"Ali 'Imran 53","quranBlocks":[{"keys":["3:53"],"basmala":false}]},"quran-3-147":{"title":"Steadfastness and victory","meaning":"[3:147] And their words were not but that they said, \"Our Lord, forgive us our sins and the excess [committed] in our affairs and plant firmly our feet and give us victory over the disbelieving people.\"","arabicSha256":"46243800ba037e6888029dd2d24982cdd0ab7f041a61cf259165ab4ee1a03287","reference":"Ali 'Imran 147","quranBlocks":[{"keys":["3:147"],"basmala":false}]},"quran-3-193":{"title":"Faith and forgiveness of sins","meaning":"[3:193] Our Lord, indeed we have heard a caller calling to faith, [saying], 'Believe in your Lord,' and we have believed. Our Lord, so forgive us our sins and remove from us our misdeeds and cause us to die with the righteous.","arabicSha256":"bc0db947a9236f3f1178dfb7547cf6eb6a49f7793c98263839747673e672fc15","reference":"Ali 'Imran 193","quranBlocks":[{"keys":["3:193"],"basmala":false}]},"quran-3-194":{"title":"Asking for Allah's bounty","meaning":"[3:194] Our Lord, and grant us what You promised us through Your messengers and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in [Your] promise.\"","arabicSha256":"050f77e4f250326d2081485bac14fc73870a5927e2566a4d3087b06a37cc254f","reference":"Ali 'Imran 194","quranBlocks":[{"keys":["3:194"],"basmala":false}]},"quran-7-23":{"title":"Repentance and mercy","meaning":"[7:23] They said, \"Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers.\"","arabicSha256":"a57d400df1b54457b00d95adeba422c36e46219d39a766bd5989ace423ab986e","reference":"Al-A'raf 23","quranBlocks":[{"keys":["7:23"],"basmala":false}]},"quran-7-126":{"title":"Patience and steadfastness","meaning":"[7:126] And you do not resent us except because we believed in the signs of our Lord when they came to us. Our Lord, pour upon us patience and let us die as Muslims [in submission to You].\"","arabicSha256":"fe0fdca7d325defb87d8b04e85c5a5fc3ff519a076ecbdc1f1e1a6701fa485d7","reference":"Al-A'raf 126","quranBlocks":[{"keys":["7:126"],"basmala":false}]},"quran-14-40":{"title":"Establishing prayer","meaning":"[14:40] My Lord, make me an establisher of prayer, and [many] from my descendants. Our Lord, and accept my supplication.","arabicSha256":"dc36e7226fee20216e843de872c7e946339af162260d1fbfdeef3e63451eb9d4","reference":"Ibrahim 40","quranBlocks":[{"keys":["14:40"],"basmala":false}]},"quran-14-41":{"title":"Forgiveness for one's parents","meaning":"[14:41] Our Lord, forgive me and my parents and the believers the Day the account is established.\"","arabicSha256":"074285ce00984cfe0e52c6913690d5b96357b95bf3b3edd0d507b8b688bddab4","reference":"Ibrahim 41","quranBlocks":[{"keys":["14:41"],"basmala":false}]},"quran-17-24":{"title":"Mercy for one's parents","meaning":"[17:24] And lower to them the wing of humility out of mercy and say, \"My Lord, have mercy upon them as they brought me up [when I was] small.\"","arabicSha256":"e9a5277b26023b4a29c6f9d0286daeae79918cc3b8ae3c0ee2cdc98c549f9982","reference":"Al-Isra 24","quranBlocks":[{"keys":["17:24"],"basmala":false}]},"quran-18-10":{"title":"Mercy and right guidance","meaning":"[18:10] [Mention] when the youths retreated to the cave and said, \"Our Lord, grant us from Yourself mercy and prepare for us from our affair right guidance.\"","arabicSha256":"e9c64f0de27d488290bc53b98ad06442a9f3da1ae07e042d43f7ea8ac6d24b9c","reference":"Al-Kahf 10","quranBlocks":[{"keys":["18:10"],"basmala":false}]},"quran-20-114":{"title":"An increase in knowledge","meaning":"[20:114] So high [above all] is Allah, the Sovereign, the Truth. And, [O Muhammad], do not hasten with [recitation of] the Qur'an before its revelation is completed to you, and say, \"My Lord, increase me in knowledge.\"","arabicSha256":"2e7ab486924b0ba8d62465851de8571d75b05f553e636b20d18321e68e4662ff","reference":"Ta-Ha 114","quranBlocks":[{"keys":["20:114"],"basmala":false}]},"quran-21-83":{"title":"Relief from affliction","meaning":"[21:83] And [mention] Job, when he called to his Lord, \"Indeed, adversity has touched me, and you are the Most Merciful of the merciful.\"","arabicSha256":"9c226d31f8280a8ad4a28a9105db8bc0275eca6df923dad0fefe539b416f9516","reference":"Al-Anbya 83","quranBlocks":[{"keys":["21:83"],"basmala":false}]},"quran-21-87":{"title":"Glorification and repentance","meaning":"[21:87] And [mention] the man of the fish, when he went off in anger and thought that We would not decree [anything] upon him. And he called out within the darknesses, \"There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers.\"","arabicSha256":"6ae9ff8cc324b8b48ed0d3a24d696489d20e92ffdcb6e931cf290d02cd71d3c4","reference":"Al-Anbya 87","quranBlocks":[{"keys":["21:87"],"basmala":false}]},"quran-23-97":{"title":"Seeking refuge in Allah","meaning":"[23:97] And say, \"My Lord, I seek refuge in You from the incitements of the devils,","arabicSha256":"bfec1d0c986dccf7e8dc9b83273bf7fa77d8c7897be64380f81ad712900d12d2","reference":"Al-Mu'minun 97","quranBlocks":[{"keys":["23:97"],"basmala":false}]},"quran-23-109":{"title":"Faith and mercy","meaning":"[23:109] Indeed, there was a party of My servants who said, 'Our Lord, we have believed, so forgive us and have mercy upon us, and You are the best of the merciful.'","arabicSha256":"275eed61b0fa4752fd672292582c5b9223812739cb10ad27d4e8b899326fafa2","reference":"Al-Mu'minun 109","quranBlocks":[{"keys":["23:109"],"basmala":false}]},"quran-23-118":{"title":"Forgiveness and mercy","meaning":"[23:118] And, [O Muhammad], say, \"My Lord, forgive and have mercy, and You are the best of the merciful.\"","arabicSha256":"bd9b995c5888bc0b4587ce60e80c8f9e3d2c4d98ce4462e75d20b4c53914b1e7","reference":"Al-Mu'minun 118","quranBlocks":[{"keys":["23:118"],"basmala":false}]},"quran-25-65":{"title":"Deliverance from punishment","meaning":"[25:65] And those who say, \"Our Lord, avert from us the punishment of Hell. Indeed, its punishment is ever adhering;","arabicSha256":"9fb66d9ffdb6c6e562fb37c2af0e26dfdf9c5681979b0de31f297eb5f745b6ee","reference":"Al-Furqan 65","quranBlocks":[{"keys":["25:65"],"basmala":false}]},"quran-25-74":{"title":"Righteous family and descendants","meaning":"[25:74] And those who say, \"Our Lord, grant us from among our wives and offspring comfort to our eyes and make us an example for the righteous.\"","arabicSha256":"4b38d9ddff8b05ed04ab3d262a8ac74e29635482a707b605e8dab4ad1b4afe1a","reference":"Al-Furqan 74","quranBlocks":[{"keys":["25:74"],"basmala":false}]},"quran-27-19":{"title":"Gratitude for blessings","meaning":"[27:19] So [Solomon] smiled, amused at her speech, and said, \"My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to do righteousness of which You approve. And admit me by Your mercy into [the ranks of] Your righteous servants.\"","arabicSha256":"5c37a83b01ee1282100ee1a43f668992cad04ff81265c79f0d5fa08d57cc0de2","reference":"An-Naml 19","quranBlocks":[{"keys":["27:19"],"basmala":false}]},"quran-28-16":{"title":"Seeking forgiveness","meaning":"[28:16] He said, \"My Lord, indeed I have wronged myself, so forgive me,\" and He forgave him. Indeed, He is the Forgiving, the Merciful.","arabicSha256":"9e9bf3600a4a8b376ae28798b599bc0e3d84e5ea3897302c4b41fa04ac010f1e","reference":"Al-Qasas 16","quranBlocks":[{"keys":["28:16"],"basmala":false}]},"quran-28-24":{"title":"Need for Allah's provision","meaning":"[28:24] So he watered [their flocks] for them; then he went back to the shade and said, \"My Lord, indeed I am, for whatever good You would send down to me, in need.\"","arabicSha256":"4e64a30578e0cdf4f61dd9a088bf47dc4d03db2c09b2aa392bd3a01c3a5f1e5b","reference":"Al-Qasas 24","quranBlocks":[{"keys":["28:24"],"basmala":false}]},"quran-46-15":{"title":"Gratitude and righteous descendants","meaning":"[46:15] And We have enjoined upon man, to his parents, good treatment. His mother carried him with hardship and gave birth to him with hardship, and his gestation and weaning [period] is thirty months. [He grows] until, when he reaches maturity and reaches [the age of] forty years, he says, \"My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to work righteousness of which You will approve and make righteous for me my offspring. Indeed, I have repented to You, and indeed, I am of the Muslims.\"","arabicSha256":"3c113c5c9529b540fdb922334ce2e27e141604ce4bc6a12e7b37b8d81b319ab2","reference":"Al-Ahqaf 15","quranBlocks":[{"keys":["46:15"],"basmala":false}]},"quran-59-10":{"title":"A heart free from resentment","meaning":"[59:10] And [there is a share for] those who came after them, saying, \"Our Lord, forgive us and our brothers who preceded us in faith and put not in our hearts [any] resentment toward those who have believed. Our Lord, indeed You are Kind and Merciful.\"","arabicSha256":"ad7082ffcd020a01e0bad52b57ddf3572b7cfd1bd4d919bb85087cc0da34589e","reference":"Al-Hashr 10","quranBlocks":[{"keys":["59:10"],"basmala":false}]},"quran-66-8":{"title":"Perfecting our light and forgiveness","meaning":"[66:8] O you who have believed, repent to Allah with sincere repentance. Perhaps your Lord will remove from you your misdeeds and admit you into gardens beneath which rivers flow [on] the Day when Allah will not disgrace the Prophet and those who believed with him. Their light will proceed before them and on their right; they will say, \"Our Lord, perfect for us our light and forgive us. Indeed, You are over all things competent.\"","arabicSha256":"6be36a52631ebaf593747c63771d1072d8eaa3f70ce3018f6b0b08863b0bb98e","reference":"At-Tahrim 8","quranBlocks":[{"keys":["66:8"],"basmala":false}]},"quran-66-11":{"title":"Asking for Paradise","meaning":"[66:11] And Allah presents an example of those who believed: the wife of Pharaoh, when she said, \"My Lord, build for me near You a house in Paradise and save me from Pharaoh and his deeds and save me from the wrongdoing people.\"","arabicSha256":"2eea37c0fad09026d9299c48bee380f146814c0e7f60ff4e6de7f6620b9c0b49","reference":"At-Tahrim 11","quranBlocks":[{"keys":["66:11"],"basmala":false}]},"quran-taha":{"title":"An open heart and ease in one's affairs","meaning":"[20:25] [Moses] said, \"My Lord, expand for me my breast [with assurance]\n[20:26] And ease for me my task\n[20:27] And untie the knot from my tongue\n[20:28] That they may understand my speech.","arabicSha256":"370587683d7def69b7e2c9534d7b1ee3e9c33a80ca5f6e75a0502d3008cca50e","reference":"Ta-Ha 25–28","quranBlocks":[{"keys":["20:25","20:26","20:27","20:28"],"basmala":false}]},"muslim-375a":{"title":"When entering the toilet","meaning":"O Allah, I seek refuge in You from male and female devils.","arabicSha256":"663a552860d0e33b1f9a00aed0733b5112343ff9aa057f242da840c8b26ee187","reference":"Sahih Muslim 375a"},"muslim-405":{"title":"Blessings upon the Prophet: Abu Mas'ud's narration","meaning":"O Allah, bestow blessings upon Muhammad and the family of Muhammad as You bestowed blessings upon the family of Abraham. Grant blessing to Muhammad and the family of Muhammad as You granted blessing to the family of Abraham among all peoples. You are Praiseworthy, Glorious.","arabicSha256":"65656f4eb9bbb5cbc40520bba8d1d72523cbb12baaf899d07af4c286eb0f448d","reference":"Sahih Muslim 405"},"muslim-406a":{"title":"Blessings upon the Prophet: Ka'b's narration","meaning":"O Allah, bestow blessings upon Muhammad and the family of Muhammad as You bestowed blessings upon the family of Abraham. You are Praiseworthy, Glorious. O Allah, grant blessing to Muhammad and the family of Muhammad as You granted blessing to the family of Abraham. You are Praiseworthy, Glorious.","arabicSha256":"f80fc26810d5bceb8b9878fca5ab6598870082681671dfe568c95fc0f617e999","reference":"Sahih Muslim 406a"},"muslim-471b":{"title":"Praise after rising from bowing","meaning":"O Allah, our Lord, to You belongs praise filling the heavens, filling the earth, and filling whatever else You will. You are worthy of praise and glory. None can withhold what You give, and none can give what You withhold. No wealth or status can benefit its possessor against You.","arabicSha256":"03d23cced832a98a1c4a448080175451be9781f1c8f8fd42eaf31a67a5abb9f2","reference":"Sahih Muslim 471b"},"muslim-476c":{"title":"Praise and purification after bowing","meaning":"O Allah, to You belongs praise filling heaven, filling the earth, and filling whatever else You will. O Allah, purify me with snow, hail and cold water. O Allah, purify me of sins and wrongdoing as a white garment is cleansed of dirt.","arabicSha256":"bd47bc5a7a0d8474e5aa6444e2e5c06db817520cf8f38d7e427e556154a603e8","reference":"Sahih Muslim 476c"},"muslim-477":{"title":"Worthy of praise and glory","meaning":"Our Lord, to You belongs praise filling the heavens and the earth, and filling whatever else You will. You are worthy of praise and glory, the truest words a servant can say, and we are all Your servants. O Allah, none can withhold what You give, and none can give what You withhold. No wealth or status can benefit its possessor against You.","arabicSha256":"2c533c166ef75f155cf3f388387eef4d6e7d92aaec63a626244ef3bcebd6c4b9","reference":"Sahih Muslim 477"},"muslim-483":{"title":"Forgiveness in prostration","meaning":"O Allah, forgive all my sins: the small and the great, the first and the last, the public and the secret.","arabicSha256":"19ab7a1dc537eb455446650792f84bcd181712b3b03a50948755678c7eb899d9","reference":"Sahih Muslim 483"},"muslim-484a":{"title":"Glorification and forgiveness in bowing and prostration","meaning":"Glory be to You, O Allah, our Lord, and praise be to You. O Allah, forgive me.","arabicSha256":"4370bd68669fd0d5f18fa838113948a844ed59a3d94356cff47cae68c8abcda9","reference":"Sahih Muslim 484a"},"muslim-485":{"title":"Glorification and oneness in bowing and prostration","meaning":"Glory be to You, and praise be to You. There is no god but You.","arabicSha256":"f5a766929668f3c9962c94c921a959723968430dc529b89021e4df45da54a337","reference":"Sahih Muslim 485"},"muslim-486":{"title":"Supplication in prostration","meaning":"O Allah, I seek refuge in Your pleasure from Your anger, and in Your pardon from Your punishment. I seek refuge in You from You. I cannot fully praise You; You are as You have praised Yourself.","arabicSha256":"a89bfc220a950fb7bf5f4eecd17accca48b01dc25c48320ed60f5482f3c697fc","reference":"Sahih Muslim 486"},"muslim-589":{"title":"Seeking refuge before ending prayer","meaning":"O Allah, I seek refuge in You from punishment in the grave. I seek refuge in You from the trial of the false messiah, and I seek refuge in You from the trials of life and death. O Allah, I seek refuge in You from sin and debt.","arabicSha256":"8b002211c41b9faa016cc13732321eb44ad2f7e6338b011e042c9304a4e5ef6a","reference":"Sahih Muslim 589"},"muslim-588c":{"title":"Seeking refuge after the tashahhud","meaning":"O Allah, I seek refuge in You from punishment in the grave, punishment in the Fire, the trials of life and death, and the evil of the false messiah.","arabicSha256":"5c6c867f44b2faf76091e0de1e2326fb5c0790726335fd117c6565cd7fefce88","reference":"Sahih Muslim 588c"},"muslim-591":{"title":"O Allah, You are Peace","meaning":"O Allah, You are Peace and from You comes peace. Blessed are You, Possessor of majesty and honour.","arabicSha256":"3840c67e4e5a5e049559fab53d9d6c6f134a9da0104eefb5b918eb48ee2f030d","reference":"Sahih Muslim 591"},"muslim-593a":{"title":"Oneness and supplication after prayer","meaning":"There is no god but Allah alone, with no partner. To Him belong sovereignty and praise, and He has power over all things. O Allah, none can withhold what You give, and none can give what You withhold. No wealth or status can benefit its possessor against You.","arabicSha256":"015d66a71aededd88c9bd336dbfb891add93767b4937cbd8f7166a2ef84b1e4d","reference":"Sahih Muslim 593a"},"muslim-594a":{"title":"Oneness and sincere devotion after prayer","meaning":"There is no god but Allah alone, with no partner. To Him belong sovereignty and praise, and He has power over all things. There is no power and no strength except through Allah. There is no god but Allah, and we worship none but Him. To Him belong blessing, bounty and beautiful praise. There is no god but Allah; we devote our religion sincerely to Him, even if the disbelievers dislike it.","arabicSha256":"8c13fc821bbb3865711ae739f748513fafa1239d391d8ddf13f977b3e3871ebc","reference":"Sahih Muslim 594a"},"muslim-598a-b":{"title":"Opening supplication of prayer","meaning":"O Allah, put distance between me and my sins as You have put distance between the east and the west. O Allah, cleanse me of my sins as a white garment is cleansed of dirt. O Allah, wash away my sins with snow, water and hail.","arabicSha256":"09388ac3e400f764974758457e4c26bc7746d962e124cfe0e7b75c889bb2293d","reference":"Sahih Muslim 598a-b"},"muslim-713a":{"title":"Entering the mosque","meaning":"O Allah, open for me the gates of Your mercy.","arabicSha256":"ba5d9d688cc88dfd23eb9d17f413355f889801ddceb508c4adf94b44c51bc069","reference":"Sahih Muslim 713a"},"muslim-763a":{"title":"Asking for light when going to prayer","meaning":"O Allah, place light in my heart, light in my sight, light in my hearing, light on my right, light on my left, light above me, light below me, light in front of me and light behind me, and make my light great.","arabicSha256":"2d0eed4f373d6b3ab1ae89f1464e2db78dc43709523e5db7017b31443eeb0ba0","reference":"Sahih Muslim 763a"},"muslim-763l":{"title":"Asking for light: another narration","meaning":"O Allah, place light in my heart and light on my tongue. Place light in my hearing and light in my sight. Place light behind me and light in front of me. Place light above me and light below me. O Allah, give me light.","arabicSha256":"833f15828f5861d16291715eae2d1b891c650d7285f0bcdfe1ba428411cd0545","reference":"Sahih Muslim 763l"},"muslim-769a":{"title":"Opening supplication of night prayer","meaning":"O Allah, to You belongs praise. You are the Light of the heavens and the earth. To You belongs praise. You sustain the heavens and the earth. To You belongs praise. You are Lord of the heavens and the earth and all who are in them. You are the Truth; Your promise is true; Your word is true; meeting You is true; Paradise is true; the Fire is true; and the Hour is true. O Allah, to You I submit, in You I believe, upon You I rely, to You I turn, through You I argue my case, and to You I bring my disputes for judgement. Forgive what I have done and what I have yet to do, what I have concealed and what I have made public. You are my God; there is no god but You.","arabicSha256":"a3e13095ccdbec098dbe11efdba9563f600368ae2c40b88e91a89f39c462b4bd","reference":"Sahih Muslim 769a"},"muslim-770":{"title":"Opening night prayer: seeking guidance","meaning":"O Allah, Lord of Gabriel, Michael and Israfil, Originator of the heavens and the earth, Knower of the unseen and the seen: You judge between Your servants concerning their disagreements. Guide me, by Your permission, to the truth over which people differ. You guide whom You will to a straight path.","arabicSha256":"d0d3a0a626f97e70932131cfb67e88ae8184b2c928e7c9b3054c5ca83d2f926d","reference":"Sahih Muslim 770"},"muslim-771a":{"title":"Opening prayer: turning to Allah","meaning":"I have turned my face towards the One who originated the heavens and the earth, inclining to the truth, and I am not one of those who associate partners with Him. My prayer, my sacrifice, my life and my death are for Allah, Lord of all worlds, with no partner. This is what I have been commanded, and I am one of those who submit. O Allah, You are the Sovereign; there is no god but You. You are my Lord and I am Your servant. I have wronged myself and acknowledged my sin, so forgive all my sins, for none forgives sins but You. Guide me to the best character, for none guides to the best of it but You. Turn bad character away from me, for none turns it away from me but You. I am here in Your service, ready to obey You. All good is in Your hands, and evil is not attributed to You. I exist through You and return to You. Blessed and exalted are You. I seek Your forgiveness and turn to You in repentance.","arabicSha256":"37a0b7cd0a39e3656883304c0ab582ee4d6f17bc92ce5a8e8a5f53ffc08a2100","reference":"Sahih Muslim 771a"},"muslim-772":{"title":"Glorification in bowing","meaning":"Glory be to my Lord, the Magnificent.","arabicSha256":"b26e15b6991d0a647fda3ec0e7aa86db7052369b0655014eaa159f989e8a09cc","reference":"Sahih Muslim 772"},"muslim-897a":{"title":"Asking for rain","meaning":"O Allah, send us rain. O Allah, send us rain. O Allah, send us rain.","arabicSha256":"3dbc4f7dac42b81f49d2e89e42bb85859c22c40431e0a19e93e06daf2e21b426","reference":"Sahih Muslim 897a"},"muslim-899b":{"title":"When the wind blows","meaning":"O Allah, I ask You for its good, the good within it, and the good it was sent with. I seek refuge in You from its evil, the evil within it, and the evil it was sent with.","arabicSha256":"053c9e9847cffcaf65c0f5722fbb89cc40c2ddb356a51282ea87f35d326a3fd4","reference":"Sahih Muslim 899b"},"muslim-963a":{"title":"For the deceased: 'Awf's narration","meaning":"O Allah, forgive him, have mercy on him, grant him well-being and pardon him. Honour his reception and make his entrance spacious. Wash him with water, snow and hail, and cleanse him of sins as You cleanse a white garment of dirt. Replace his home with a better home, his family with a better family, and his spouse with a better spouse. Admit him to Paradise, and protect him from punishment in the grave or punishment in the Fire.","arabicSha256":"705030e9ea7d2bab6d7d13f83075f07b4f66e48484cbd8a164ffbbfb5af06cad","reference":"Sahih Muslim 963a"},"muslim-963d":{"title":"For the deceased: another narration","meaning":"O Allah, forgive him, have mercy on him, pardon him and grant him well-being. Honour his reception and make his entrance spacious. Wash him with water, snow and hail, and cleanse him of sins as a white garment is cleansed of dirt. Replace his home with a better home, his family with a better family, and his spouse with a better spouse. Protect him from the trial of the grave and punishment in the Fire.","arabicSha256":"8bd38894def2bf941ee3de532ed94cefaf9bc3ab63a6238ec54b4ff3ab3b3810","reference":"Sahih Muslim 963d"},"muslim-974a":{"title":"For the people of al-Baqi'","meaning":"Peace be upon you, dwelling of believing people. What you were promised has come to you; you await what is to come tomorrow. If Allah wills, we will join you. O Allah, forgive the people of Baqi' al-Gharqad.","arabicSha256":"c942e5d13828b678a6571102ba346ad3df3de112861ab2417ff64190ab21b7a0","reference":"Sahih Muslim 974a"},"muslim-1055":{"title":"For the Prophet's family: sufficient provision","meaning":"O Allah, make the provision of the family of Muhammad sufficient for their needs.","arabicSha256":"67b64d2d7163e7bfc46acc900e41bc9ee195ed5899636263b5ce4e515b886c87","reference":"Sahih Muslim 1055"},"muslim-1184a":{"title":"Talbiyah for Hajj and 'Umrah","meaning":"Here I am, O Allah, here I am. Here I am; You have no partner; here I am. All praise, blessing and sovereignty belong to You. You have no partner.","arabicSha256":"55d9ce5ca0c9bc18b6347f2edafaf13b9de535ad7049f19c772bb9f2efd161b8","reference":"Sahih Muslim 1184a"},"muslim-1342":{"title":"When travelling","meaning":"Glory be to the One who has subjected this to us, for we could not have subdued it ourselves, and to our Lord we shall surely return. O Allah, we ask You on this journey for righteousness, piety, and deeds that please You. O Allah, make this journey easy for us and shorten its distance. O Allah, You are the Companion on the journey and the Guardian of the family left behind. O Allah, I seek refuge in You from the hardships of travel, a distressing sight, and an ill return concerning wealth and family.","arabicSha256":"39fe3252389defd072a19804c13191c51a63f11f4f2dcde7f9f47f926034163a","reference":"Sahih Muslim 1342"},"muslim-1434a":{"title":"Before marital intimacy","meaning":"In the name of Allah. O Allah, keep Satan away from us, and keep Satan away from what You provide for us.","arabicSha256":"0ac3517d70f2d827fcb4dacbd90637f3113187d8a58a4be7d26a48ae493be59b","reference":"Sahih Muslim 1434a"},"muslim-1792a":{"title":"Forgiveness for one's people","meaning":"O Allah, forgive my people, for they do not know.","arabicSha256":"b3116f0e8f441b7bcefa7ca78667d9f38a5dbb0ba46dad3fd4cdd8e916c6960c","reference":"Sahih Muslim 1792a"},"muslim-1804":{"title":"For the Emigrants and the Helpers","meaning":"O Allah, there is no life but the life of the Hereafter, so forgive the Emigrants and the Helpers.","arabicSha256":"c8417afd73445b992800f3bfb2e2563bdc8634a861ea3be034f9942beeaa807a","reference":"Sahih Muslim 1804"},"muslim-2055a":{"title":"For someone who gives you food or drink","meaning":"O Allah, feed the one who has fed me, and give drink to the one who has given me drink.","arabicSha256":"2fa11a325bf33f5f8124b7909b6a193b22c1f41a109c954534106c9fc425ca92","reference":"Sahih Muslim 2055a"},"muslim-2186":{"title":"Ruqyah in Allah's name","meaning":"In the name of Allah, I perform ruqyah for you against everything that harms you, against the evil of every soul or envious eye. May Allah heal you. In the name of Allah, I perform ruqyah for you.","arabicSha256":"4df0113b5508db481b85c91bd5e5a68748c169e72145e886f97c354266764c53","reference":"Sahih Muslim 2186"},"muslim-2191a":{"title":"Healing and ruqyah","meaning":"Remove the affliction, Lord of mankind, and heal, for You are the Healer. There is no healing but Your healing: a healing that leaves no illness.","arabicSha256":"8544b947d9376d6bd3cc18fa677ca30881e0a992b25539ee023521baaa6c4bc1","reference":"Sahih Muslim 2191a"},"pain-bismillah":{"title":"Allah's name when in pain","meaning":"In the name of Allah.","arabicSha256":"1af75146a13a98249deaa3e778783d51403645ab541679692f6727479c03e37c","reference":"Sahih Muslim 2202"},"muslim-2202":{"title":"Seeking refuge when in pain","meaning":"I seek refuge in Allah and His power from the evil of what I feel and fear.","arabicSha256":"0224ec07ee165b2a2cf8ce66596013ac782345e1a5f21e5ccf7b2dc9574fc431","reference":"Sahih Muslim 2202"},"muslim-2444a":{"title":"During the Prophet's illness: another narration","meaning":"O Allah, forgive me, have mercy on me, and join me with the company of the righteous.","arabicSha256":"83a80c92ac6203014316ecdc7cc1211fcb2f088e62e00fe69fc0d0357946afdc","reference":"Sahih Muslim 2444a"},"muslim-2480a":{"title":"For Anas: blessing in wealth and children","meaning":"O Allah, increase his wealth and his children, and bless what You have given him.","arabicSha256":"efe5a4e6257e21984c1495cf2cb751db6d2e4b5f5d1acf1ee4ccb5603884fbb1","reference":"Sahih Muslim 2480a"},"muslim-2690a":{"title":"Good in this world and the Hereafter","meaning":"O Allah, grant us good in this world and good in the Hereafter, and protect us from punishment in the Fire.","arabicSha256":"d7f8ecbee0fed1209695031885e3d7f9963c9fcefb05becd268b75cebb64c590","reference":"Sahih Muslim 2690a"},"muslim-2690b":{"title":"Our Lord, grant us good","meaning":"Our Lord, grant us good in this world and good in the Hereafter, and protect us from punishment in the Fire.","arabicSha256":"707b2c264f897dd991314b4fa720d7b333e025146f28f9af157453a5cb1a2405","reference":"Sahih Muslim 2690b"},"muslim-2697a":{"title":"Forgiveness, mercy, guidance and provision","meaning":"O Allah, forgive me, have mercy on me, guide me and provide for me.","arabicSha256":"75031a7d59768c5acf0307ad4d92f94bf7ca8a526b578867ca19ee44e62cbf03","reference":"Sahih Muslim 2697a"},"muslim-2697b":{"title":"Forgiveness, guidance, well-being and provision","meaning":"O Allah, forgive me, have mercy on me, guide me, grant me well-being and provide for me.","arabicSha256":"21d84726da9992604d34b7165a439b538bb6f6e4fc58c278dd69e4f8253d8eac","reference":"Sahih Muslim 2697b"},"muslim-2706a":{"title":"Refuge from inability and laziness","meaning":"O Allah, I seek refuge in You from inability, laziness, cowardice, old age and miserliness. I seek refuge in You from punishment in the grave and from the trials of life and death.","arabicSha256":"ef33b8837d793ca934f78556e1d343b44ea029b4d91c40bff69829675308c771","reference":"Sahih Muslim 2706a"},"muslim-2706d":{"title":"Refuge from miserliness and laziness","meaning":"O Allah, I seek refuge in You from miserliness, laziness, the infirmity of old age, punishment in the grave, and the trials of life and death.","arabicSha256":"36a77b170cc105bcf1ef1313283d38b4e02cbcf3650a28fd6f8ba009cf3a1230","reference":"Sahih Muslim 2706d"},"muslim-2708a":{"title":"When stopping at a place","meaning":"I seek refuge in the perfect words of Allah from the evil of what He has created.","arabicSha256":"39bc09969e681187bdbcf4838e2a43c1ad23ed786565f7cc7a9a530c2877e7d7","reference":"Sahih Muslim 2708a"},"muslim-2710a":{"title":"Entrusting your affairs to Allah before sleep","meaning":"O Allah, I have submitted my face to You, entrusted my affairs to You, and sought refuge with You, out of hope in You and fear of You. There is no refuge and no escape from You except in You. I believe in Your Book which You have revealed and in Your Prophet whom You have sent.","arabicSha256":"3b2e2026b5275879f312c554dc87277e8dc65acbdb19e69237a87eba1b15d85e","reference":"Sahih Muslim 2710a"},"muslim-2710c":{"title":"Before sleep: another narration","meaning":"O Allah, I have submitted myself to You, turned my face to You, sought refuge with You, and entrusted my affairs to You, out of hope in You and fear of You. There is no refuge and no escape from You except in You. I believe in Your Book which You have revealed and in Your Messenger whom You have sent.","arabicSha256":"46063341a59e82c59249e3506c65694e20935b642f7dd434d663e999e895571d","reference":"Sahih Muslim 2710c"},"muslim-2711":{"title":"Supplication before sleep","meaning":"O Allah, in Your name I live, and in Your name I die.","arabicSha256":"9437032d6f5bdbf34b58fabf30a2cb77edda59240667cf87e0b607fc0773b615","reference":"Sahih Muslim 2711"},"muslim-2712":{"title":"Protection and well-being before sleep","meaning":"O Allah, You created my soul and You take it at death. Its death and its life belong to You. If You keep it alive, protect it; and if You take it, forgive it. O Allah, I ask You for well-being.","arabicSha256":"c6a9ab58b46637c120d2b22dbe24f553f2da6e7358cc5b2b8929688b55c7e2f6","reference":"Sahih Muslim 2712"},"muslim-2713a":{"title":"Before sleep: relief from debt","meaning":"O Allah, Lord of the heavens, Lord of the earth, and Lord of the mighty Throne, our Lord and Lord of all things, Splitter of the seed and the date-stone, Revealer of the Torah, the Gospel and the Criterion: I seek refuge in You from the evil of everything whose forelock You hold. O Allah, You are the First, and there is nothing before You. You are the Last, and there is nothing after You. You are the Most High, and there is nothing above You. You are the Most Near, and there is nothing nearer than You. Settle our debt and free us from poverty.","arabicSha256":"424d9ae813b3818b2c397e62a98a112a070b585cb0dcc6abaf435b90af5ce309","reference":"Sahih Muslim 2713a"},"muslim-2714a":{"title":"When lying down on your side","meaning":"Glory be to You, O Allah, my Lord. Through You I lay down my side, and through You I raise it. If You take my soul, forgive it; and if You release it, protect it as You protect Your righteous servants.","arabicSha256":"288816822c3d9b6e61cf870516a6a9e8b81a33e3d2688e315a6928d9c96a901d","reference":"Sahih Muslim 2714a"},"muslim-2715":{"title":"Praise before sleep","meaning":"All praise belongs to Allah, who has fed us, given us drink, provided for us and sheltered us. How many have no one to provide for them and no one to shelter them!","arabicSha256":"352880797bffdec1e04232f2898d48923a2daf1dda4408ed0e4ec2496383e368","reference":"Sahih Muslim 2715"},"muslim-2716a":{"title":"Refuge from the evil of one's deeds","meaning":"O Allah, I seek refuge in You from the evil of what I have done and the evil of what I have not done.","arabicSha256":"fd7e7406d2e98a38eddb1cd6b94e57425214a62a20d3a5fa7487526a038c9b2e","reference":"Sahih Muslim 2716a"},"muslim-2717":{"title":"Trust, repentance and refuge","meaning":"O Allah, to You I submit, in You I believe, upon You I rely, to You I turn, and through You I argue my case. O Allah, I seek refuge in Your might—there is no god but You—from being led astray. You are the Ever-Living who does not die, while jinn and humans die.","arabicSha256":"9b15dae0aa5585aad6acbfe185a73d70819c40dbf375aff5f6b823662493b84d","reference":"Sahih Muslim 2717"},"muslim-2718":{"title":"At dawn while travelling","meaning":"Let whoever hears convey our praise of Allah and His gracious favours to us. Our Lord, accompany us and bestow Your bounty upon us. I seek refuge in Allah from the Fire.","arabicSha256":"0591210c8f3bfb2538b263a43d09bf282605e6a856bf3bcb12f83d8368324d77","reference":"Sahih Muslim 2718"},"muslim-2719a":{"title":"Forgiveness for mistakes and deliberate sins","meaning":"O Allah, forgive my sin, my ignorance, my excess in my affairs, and what You know better than I do. O Allah, forgive what I have done seriously and in jest, by mistake and deliberately; all of that is in me. O Allah, forgive what I have done and what I have yet to do, what I have concealed and what I have made public, and what You know better than I do. You are the One who brings forward and the One who delays, and You have power over all things.","arabicSha256":"0e25fc86bb17568389f6a5a3c0e69da944eb02b5a6d403a9d2b418cf9612a80f","reference":"Sahih Muslim 2719a"},"muslim-2720":{"title":"Well-being in faith, life and the Hereafter","meaning":"O Allah, set right my religion, which safeguards my affairs. Set right my worldly life, in which is my livelihood. Set right my Hereafter, to which I shall return. Make life an increase for me in every good, and make death a rest for me from every evil.","arabicSha256":"c4bf0a11b343ee5eaa30dcb292d0ac75e7ffd548378f6e4f81a5f173bccc693a","reference":"Sahih Muslim 2720"},"muslim-2721a":{"title":"Guidance, piety, chastity and self-sufficiency","meaning":"O Allah, I ask You for guidance, righteousness, chastity and self-sufficiency.","arabicSha256":"64b13693f36e4cf50f626b68d7bc11b89ac2f11ddfb8b9d4eefc2fe47586d4cb","reference":"Sahih Muslim 2721a"},"muslim-2722":{"title":"Purifying the soul and seeking refuge","meaning":"O Allah, I seek refuge in You from inability, laziness, cowardice, miserliness, old age and punishment in the grave. O Allah, grant my soul its piety and purify it; You are the best to purify it. You are its Guardian and Master. O Allah, I seek refuge in You from knowledge that does not benefit, a heart that does not humble itself, a soul that is never satisfied, and a supplication that is not answered.","arabicSha256":"9d7cfef7ae088d5b6595a64e33b8d5f3959e13b580c12b12a32570af585e996a","reference":"Sahih Muslim 2722"},"muslim-2725a":{"title":"Guidance and right judgement","meaning":"O Allah, guide me and keep me on the right course.","arabicSha256":"1367f66b2287ee91397615047218d67f0a90e23d1714d294aa7a8e3fe486236e","reference":"Sahih Muslim 2725a"},"muslim-2726a":{"title":"Juwayriyah's glorification","meaning":"Glory be to Allah, and praise be to Him, as many times as His creation, as much as pleases Him, as weighty as His Throne, and as abundant as the ink of His words.","arabicSha256":"3457ca2b9aadcf637d0b54e5e911c06b2fc522bdc15aea521beb78bd5c4c374f","reference":"Sahih Muslim 2726a"},"muslim-2702a":{"title":"Seeking forgiveness during the day","meaning":"I seek Allah's forgiveness.","arabicSha256":"9ef913a347672f03b6c0b851c3a052ebd52c61a9ff40c76f1e76d932d031117f","reference":"Sahih Muslim 2702a"},"muslim-2730a":{"title":"In distress","meaning":"There is no god but Allah, the Magnificent, the Forbearing. There is no god but Allah, Lord of the mighty Throne. There is no god but Allah, Lord of the heavens, Lord of the earth and Lord of the noble Throne.","arabicSha256":"b8ab65b7ddd500ee20a7a59087caf6cf43bb4cd0dff0f8e3fa74c9ee0dafe4ba","reference":"Sahih Muslim 2730a"},"muslim-2739":{"title":"Refuge from losing blessings","meaning":"O Allah, I seek refuge in You from the loss of Your blessings, a change in the well-being You grant, the sudden arrival of Your punishment, and all that displeases You.","arabicSha256":"27878803ff9a9e623077bcd25a22ea4323a013e7549a767a11bb38a6a0db41af","reference":"Sahih Muslim 2739"},"muslim-2680a":{"title":"When suffering becomes severe","meaning":"O Allah, keep me alive as long as life is better for me, and take me in death when death is better for me.","arabicSha256":"12daed2eb2b93c0b9be5a9ecea92ebf897a13abf0daf2189890110e57eaf90d7","reference":"Sahih Muslim 2680a"},"muslim-2705a":{"title":"Forgiveness and mercy","meaning":"O Allah, I have greatly wronged myself, and none forgives sins but You. Grant me forgiveness from Yourself and have mercy on me. You are the Forgiving, the Merciful.","arabicSha256":"373eac7fcd7920339d5fefefd6fb340c5c87f6c4e5952cb44b13fb64e13a8f10","reference":"Sahih Muslim 2705a"},"muslim-713a-exit":{"title":"Leaving the mosque","meaning":"O Allah, I ask You for Your bounty.","arabicSha256":"08cc07bfe5d00b020184279df823c77bf15f2dd4d154e4cc0ae155ea940ca788","reference":"Sahih Muslim 713a"},"muslim-771a-ruku":{"title":"Supplication in bowing","meaning":"O Allah, to You I bow, in You I believe, and to You I submit. My hearing, my sight, my mind, my bones and my sinews humble themselves before You.","arabicSha256":"c4bb2c7f366fbf157c50ae03738a2b9a5c737d6ea29b1f4607f482b57fccffce","reference":"Sahih Muslim 771a"},"muslim-771a-raising":{"title":"After rising from bowing","meaning":"O Allah, our Lord, to You belongs praise filling the heavens, filling the earth, filling what is between them, and filling whatever else You will.","arabicSha256":"9ef5aeff32b981828a723f0f4c31a850dd462971a3288ea29fba124b960a8192","reference":"Sahih Muslim 771a"},"muslim-771a-sujud":{"title":"Supplication in prostration","meaning":"O Allah, to You I prostrate, in You I believe, and to You I submit. My face prostrates to the One who created it, shaped it, and opened its hearing and sight. Blessed is Allah, the best of creators.","arabicSha256":"d78a3c96644b98410f38e717d6a9db01c9ff8d0694bfc7862d1927a7cb36cdc9","reference":"Sahih Muslim 771a"},"muslim-771a-before-salam":{"title":"Between tashahhud and the final greeting","meaning":"O Allah, forgive what I have done and what I have yet to do, what I have concealed and what I have made public, my excesses, and what You know better than I do. You are the One who brings forward and the One who delays. There is no god but You.","arabicSha256":"b27384f2c663ae82493bb90a3f678b18f85d7258bb1ee6562fa33805a3e4806c","reference":"Sahih Muslim 771a"},"muslim-772-sujud":{"title":"Glorification in prostration","meaning":"Glory be to my Lord, the Most High.","arabicSha256":"37d951dbf51ddade019d1d519db4c684f77bc80aac2e1db39fdb8cbb33e56977","reference":"Sahih Muslim 772"},"muslim-897a-excess-rain":{"title":"When heavy rain may cause harm","meaning":"O Allah, around us and not upon us. O Allah, upon the hills, the small mountains, the bottoms of valleys and the places where trees grow.","arabicSha256":"9237aaf5f38d1dd724cb613afb6e6dd29209f8be8fec8c878a7e6318c5fbcccd","reference":"Sahih Muslim 897a"},"muslim-1342-return":{"title":"On returning from a journey","meaning":"We return, repenting, worshipping, and praising our Lord.","arabicSha256":"fca2322ec5bceab2256f9af8d74d36d5c8130cfa85a4733abbb5c9f489320866","reference":"Sahih Muslim 1342"},"muslim-2191a-companion":{"title":"During the Prophet's final illness","meaning":"O Allah, forgive me and place me with the highest company.","arabicSha256":"25ed67e6c18f54afcaecfaf45a6a42c826f71e81057846258d0296e815ffb6d4","reference":"Sahih Muslim 2191a"},"audit-new-garment":{"title":"When wearing a new garment","meaning":"O Allah, all praise belongs to You. You have clothed me in it. I ask You for its good and the good for which it was made, and I seek refuge in You from its evil and the evil for which it was made.","arabicSha256":"2caa5b97e97b18943151bf6a02945ccd2dc842b2bf33f3fab10a24b510cbfde1","reference":"Sunan Abi Dawud 4020"},"audit-leave-home-safety":{"title":"Seeking protection when leaving home","meaning":"O Allah, I seek refuge in You from going astray or being led astray, slipping or being made to slip, wronging others or being wronged, and acting ignorantly or being treated ignorantly.","arabicSha256":"83f9572e8c124a9e94bc60b44062e728ae45e6184980a06bfa2b9bd06c8a4c05","reference":"Sunan Abi Dawud 5094"},"audit-qunoot":{"title":"Qunut of Witr prayer","meaning":"O Allah, guide me among those You have guided, grant me well-being among those You have granted well-being, and take me into Your care among those You have taken into Your care. Bless what You have given me, and protect me from the evil of what You have decreed. You decree and none decrees over You. Whoever You befriend is not humiliated, and whoever You oppose is not honoured. Blessed and exalted are You, our Lord.","arabicSha256":"836347045169183d9ef1c80f701e465cd203d4778169d8a2dbabf120801d2c67","reference":"Sunan Abi Dawud 1425"},"audit-between-sujud":{"title":"Between the two prostrations","meaning":"O Allah, forgive me, have mercy on me, grant me well-being, guide me and provide for me.","arabicSha256":"8688bceac2301b4a188af2e16f4bcc554015fde092bc098b6a01e396c13c768f","reference":"Sunan Abi Dawud 850"},"audit-ask-paradise":{"title":"Asking for Paradise and refuge from the Fire","meaning":"O Allah, I ask You for Paradise and seek refuge in You from the Fire.","arabicSha256":"789b759f6ad6507278ce64d217cc090fb200adb014fa3b8f9370fbe4379e0b76","reference":"Sunan Abi Dawud 792"},"audit-all-good":{"title":"Asking for all good","meaning":"O Allah, I ask You for all good, immediate and future, what I know of it and what I do not know. I seek refuge in You from all evil, immediate and future, what I know of it and what I do not know. O Allah, I ask You for the good that Your servant and Prophet asked You for, and I seek refuge in You from the evil from which Your servant and Prophet sought refuge. O Allah, I ask You for Paradise and whatever words or deeds bring one nearer to it. I seek refuge in You from the Fire and whatever words or deeds bring one nearer to it. I ask You to make every decree You have decreed for me good.","arabicSha256":"fc36eb87bb22f5cd290f9fb78091740d36bb449c4ce5fb32384178483bf59eb5","reference":"Sunan Ibn Majah 3846"},"audit-sneeze":{"title":"When sneezing","meaning":"All praise belongs to Allah.","arabicSha256":"0cde81587afebd788a3d6cc1fffecb74d4742a967f3b13d897d883bb37c70658","reference":"Sahih al-Bukhari 6224"},"audit-sneeze-response":{"title":"Responding to a sneeze","meaning":"May Allah have mercy on you.","arabicSha256":"778a75c50cf31b21026b4f90452d396038c0c0d1d494e36b141a558bd476aace","reference":"Sahih al-Bukhari 6224"},"audit-sneeze-reply":{"title":"Replying to the response after a sneeze","meaning":"May Allah guide you and set your affairs right.","arabicSha256":"528f618fc5c3846ce4788fcb18142c2ee1eb0d46bf0504b940b1dd9838f1cdbe","reference":"Sahih al-Bukhari 6224"},"audit-anger":{"title":"When angry","meaning":"I seek refuge in Allah from Satan, the accursed.","arabicSha256":"2f94e22a8ce609aa71feca88ae048a9b87b55c984e3d5224bf95dafa6df44a14","reference":"Sahih al-Bukhari 6115"},"audit-after-adhan":{"title":"After the adhan","meaning":"O Allah, Lord of this perfect call and the prayer to be established, grant Muhammad al-Wasilah and excellence, and raise him to the praiseworthy station which You have promised him.","arabicSha256":"4d25c400db93f8946fc9c97fe64ac400cdf3f888af9ecde9a9a04cd973f3fbc1","reference":"Sahih al-Bukhari 614"},"audit-hayala":{"title":"Responding to the calls to prayer and success","meaning":"There is no power and no strength except through Allah.","arabicSha256":"a8e6d5234a3ff1db28da4a622387cc84be1ad574b3d3c30cfc83d5deeee88982","reference":"Sahih Muslim 385"},"audit-shahada-adhan":{"title":"On hearing the testimony of faith in the adhan","meaning":"I bear witness that there is no god but Allah alone, with no partner, and that Muhammad is His servant and Messenger. I am content with Allah as my Lord, Muhammad as my Messenger, and Islam as my religion.","arabicSha256":"abf5938337478227ccb83745ab57767e0c4fb708659ba03240c3e149ec5c85aa","reference":"Sahih Muslim 386"},"audit-meal-praise":{"title":"Praise when the meal is finished","meaning":"All praise belongs to Allah: abundant, pure and blessed praise. Our Lord, Your bounty cannot be repaid, nor can it be left aside or dispensed with.","arabicSha256":"d63e5f132464c02fa79151156bc42a6ee30e90fd4d78b8fb0c125cc32222cc7c","reference":"Sahih al-Bukhari 5458"},"audit-rain":{"title":"On seeing rain","meaning":"A beneficial downpour.","arabicSha256":"f26e54b431c728a729f99b1d717e4184c4e6d9cd9beafb29249624cdbd3e3b37","reference":"Sahih al-Bukhari 1032"},"audit-after-rain":{"title":"After rainfall","meaning":"We have been given rain by Allah's bounty and mercy.","arabicSha256":"e4dd021fd2383ba72afeb8bad2ee1436845b12c81af08a4a94a24f754d0fb8cd","reference":"Sahih al-Bukhari 846"},"audit-condolence":{"title":"Offering condolences","meaning":"To Allah belongs what He has taken, and to Him belongs what He has given. Everything with Him has an appointed time. Be patient and seek His reward.","arabicSha256":"a4106c560587ea30050e4b5d419ced5dda9cbb7841ec2db808b3e39c7f5f70bb","reference":"Sahih al-Bukhari 1284"},"audit-food-blessing":{"title":"Asking for blessing in food","meaning":"O Allah, bless it for us and feed us something better than it.","arabicSha256":"ed25bf1bebf6ea9c8f9060f1b6ff751c925a37bb77619dff3141a8dc5a785f03","reference":"Sunan Abi Dawud 3730"},"audit-milk":{"title":"When drinking milk","meaning":"O Allah, bless it for us and feed us something better than it. When given milk to drink, one should say: O Allah, bless it for us and give us more of it.","arabicSha256":"d27dbd900279b3c46156d871194d739914aeecd56203a6488917c97b1f2f4800","reference":"Sunan Abi Dawud 3730"},"audit-host":{"title":"For one's hosts","meaning":"O Allah, bless what You have provided for them, forgive them and have mercy on them.","arabicSha256":"d6b3559400eb754e88dafa174593a6cee1c73078be6d2a29a073bb5bb61347b8","reference":"Sahih Muslim 2042a"},"audit-graves":{"title":"When visiting graves","meaning":"Peace be upon you, inhabitants of these dwellings, believers and Muslims. If Allah wills, we will join you. I ask Allah for well-being for us and for you.","arabicSha256":"e3a5ef5bd194c82c38fa164c46fb114d4bf94538e734caadbb0c89f03ec0655c","reference":"Sahih Muslim 975"},"audit-tashahhud":{"title":"The tashahhud","meaning":"All greetings, prayers and good words belong to Allah. Peace be upon you, O Prophet, and Allah's mercy and blessings. Peace be upon us and upon Allah's righteous servants. I bear witness that there is no god but Allah, and I bear witness that Muhammad is His servant and Messenger.","arabicSha256":"c8659e11bef2b0a8d97abd6098f98883a28bc24054cbcb73e586cb448d704dfa","reference":"Sahih Muslim 402a"},"audit-istikhara":{"title":"Seeking guidance in a decision","meaning":"O Allah, I seek Your choice through Your knowledge, and I seek ability through Your power. I ask You from Your immense bounty, for You have power and I do not, You know and I do not, and You are the Knower of the unseen. O Allah, if You know that this matter is good for me in my religion, my livelihood and the outcome of my affairs, decree it for me, make it easy for me, and then bless it for me. If You know that this matter is bad for me in my religion, my livelihood and the outcome of my affairs, turn it away from me and turn me away from it. Decree good for me wherever it may be, and then make me content with it.","arabicSha256":"d9d6679d2ff78be1539281cf0b9665b75636aab2730106e0446f1c60a62910d2","reference":"Sahih al-Bukhari 1166"},"post-prayer-112":{"title":"Surah Al-Ikhlas","meaning":"In the name of Allah, the Entirely Merciful, the Especially Merciful.\n[112:1] Say, \"He is Allah, [who is] One,\n[112:2] Allah, the Eternal Refuge.\n[112:3] He neither begets nor is born,\n[112:4] Nor is there to Him any equivalent.\"","arabicSha256":"37447359d456392ecb36baaca092479a6ec08d6e5c89385742d83e901dc08943","reference":"Al-Ikhlas 1–4","quranBlocks":[{"keys":["112:1","112:2","112:3","112:4"],"basmala":true}]},"post-prayer-113":{"title":"Surah Al-Falaq","meaning":"In the name of Allah, the Entirely Merciful, the Especially Merciful.\n[113:1] Say, \"I seek refuge in the Lord of daybreak\n[113:2] From the evil of that which He created\n[113:3] And from the evil of darkness when it settles\n[113:4] And from the evil of the blowers in knots\n[113:5] And from the evil of an envier when he envies.\"","arabicSha256":"355ce482a7f3f87cb7061794c3b9fbcfb8d1c830b28b293d835bab530186dd66","reference":"Al-Falaq 1–5","quranBlocks":[{"keys":["113:1","113:2","113:3","113:4","113:5"],"basmala":true}]},"post-prayer-114":{"title":"Surah An-Nas","meaning":"In the name of Allah, the Entirely Merciful, the Especially Merciful.\n[114:1] Say, \"I seek refuge in the Lord of mankind,\n[114:2] The Sovereign of mankind.\n[114:3] The God of mankind,\n[114:4] From the evil of the retreating whisperer -\n[114:5] Who whispers [evil] into the breasts of mankind -\n[114:6] From among the jinn and mankind.\"","arabicSha256":"dbe8bd9fb168c7f74898b4ce2da84cd24af7053425009f78a1ee352419570338","reference":"An-Nas 1–6","quranBlocks":[{"keys":["114:1","114:2","114:3","114:4","114:5","114:6"],"basmala":true}]},"post-prayer-kursi":{"title":"Ayat al-Kursi","meaning":"[2:255] Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.","arabicSha256":"c826c8de989a783d07855b47df70889895bfae4e99f2dbd39fdae5e2911f11d2","reference":"Al-Baqarah 255","quranBlocks":[{"keys":["2:255"],"basmala":false}]},"night-three-surahs":{"title":"The three protective surahs before sleep","meaning":"In the name of Allah, the Entirely Merciful, the Especially Merciful.\n[112:1] Say, \"He is Allah, [who is] One,\n[112:2] Allah, the Eternal Refuge.\n[112:3] He neither begets nor is born,\n[112:4] Nor is there to Him any equivalent.\"\n\nIn the name of Allah, the Entirely Merciful, the Especially Merciful.\n[113:1] Say, \"I seek refuge in the Lord of daybreak\n[113:2] From the evil of that which He created\n[113:3] And from the evil of darkness when it settles\n[113:4] And from the evil of the blowers in knots\n[113:5] And from the evil of an envier when he envies.\"\n\nIn the name of Allah, the Entirely Merciful, the Especially Merciful.\n[114:1] Say, \"I seek refuge in the Lord of mankind,\n[114:2] The Sovereign of mankind.\n[114:3] The God of mankind,\n[114:4] From the evil of the retreating whisperer -\n[114:5] Who whispers [evil] into the breasts of mankind -\n[114:6] From among the jinn and mankind.\"","arabicSha256":"bd9946877a9008be9f98a53a6a0f2ba91c78a143c763598f743c75e15683ff64","reference":"Al-Ikhlas, Al-Falaq and An-Nas in full","quranBlocks":[{"keys":["112:1","112:2","112:3","112:4"],"basmala":true},{"keys":["113:1","113:2","113:3","113:4","113:5"],"basmala":true},{"keys":["114:1","114:2","114:3","114:4","114:5","114:6"],"basmala":true}]},"audit-food-name":{"title":"Before eating","meaning":"In the name of Allah.","arabicSha256":"e04227e76e93073d4986e666c2d93df8cb9ee56e50fc400f6a93cee30b7f3513","reference":"Jami' al-Tirmidhi 1858"},"audit-garment-praise":{"title":"Praise when putting on clothes","meaning":"All praise belongs to Allah, who has clothed me in this garment and provided it for me without any power or strength on my part.","arabicSha256":"315d20f07bccbe85d17f0b39fd4379322d6fcd18c521b9a03f9a283c334df758","reference":"Sunan Abi Dawud 4023"},"audit-after-wudu":{"title":"Testimony of faith after wudu","meaning":"I bear witness that there is no god but Allah alone, with no partner, and I bear witness that Muhammad is His servant and Messenger.","arabicSha256":"e9c40909b3c1a7e92a7c29adcef67c672af4872297a9bacd4b1b06ca49d6c0cd","reference":"Sahih Muslim 234b"},"audit-meeting":{"title":"At the end of a gathering","meaning":"Glory be to You, O Allah, and praise be to You. I bear witness that there is no god but You. I seek Your forgiveness and turn to You in repentance.","arabicSha256":"6942edc63fcb3804f5da2997cea25d05c06bad51b993aea25470197b84af73f6","reference":"Jami' al-Tirmidhi 3433"},"audit-night-wake":{"title":"When waking during the night","meaning":"There is no god but Allah alone, with no partner. To Him belong sovereignty and praise, and He has power over all things. All praise belongs to Allah. Glory be to Allah. There is no god but Allah. Allah is the Greatest. There is no power and no strength except through Allah. O Allah, forgive me.","arabicSha256":"e0cb46a796866c4e8ed2e5f9f0f55f932a19a64713d5c801c66896e5f46d364e","reference":"Sahih al-Bukhari 1154"}},"arabicAssetsSha256":{"quran.js":"97909f3e04bd0433037331a1b0b52c6d03c6d25528cf3e3cb2f88cafe2395865","devotions-data.js":"bb80cb8057812dddd08db1b80f3ad57f6624023af1e997b744f2c478e3b0cafc","muslim-devotions.js":"0f38377a3d6da926fcf7f8acdb62ecdae6134762fac57ba3d4ac566ba581c1b5","morning-evening-data.js":"e5b2d6b79d949b7e72e82e1e11e314b9e529f394e76bcfe4dd76430df2cfb0ce","library-audit-data.js":"5a3652c2f97a7c13522ce5748cb357cd6fb00e881177c2a3c7f81c9cc1f59e37"}};
